const input = $json.body ?? $json;
const allowed = new Set([
  'market.open.snapshot.v1', 'market.movers.snapshot.v1',
  'market.oiis.candidates.changed.v1', 'market.close.snapshot.v1'
]);
const required = ['schema','event_id','event_type','trade_date','generated_at','data_as_of','timezone','dedupe_key','correlation_id','source','quality','payload'];
if (required.some((key) => input[key] === undefined) || input.schema !== 'market-status-whatsapp.v1' ||
    input.environment !== 'MARKET_INTELLIGENCE' || input.timezone !== 'Asia/Kolkata' || !allowed.has(input.event_type)) {
  throw new Error('UNSUPPORTED_OR_INVALID_MARKET_STATUS_EVENT');
}
const n = (value, digits=2) => new Intl.NumberFormat('en-IN',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(Number(value));
const signed = (value, suffix='') => {
  const number = Number(value); return (number > 0 ? '+' : '') + n(number) + suffix;
};
const ist = (value) => new Date(value).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}) + ' IST';
const p = input.payload;
let lines = [];
switch (input.event_type) {
  case 'market.open.snapshot.v1':
    lines = ['*NIFTY 50 — OPEN*', 'Level *' + n(p.current_level) + '* · ' + signed(p.point_change,' pts') + ' (' + signed(p.percentage_change,'%') + ')',
      'Open ' + n(p.session_open) + ' · Gap ' + signed(p.gap_percentage,'%') + ' · From open ' + signed(p.move_from_open_percentage,'%'),
      'Range ' + n(p.session_low) + '–' + n(p.session_high) + ' · ' + ist(input.data_as_of)];
    break;
  case 'market.movers.snapshot.v1':
    lines = ['*NIFTY 50 MOVERS — 09:20*','*Gainers*'];
    for (const row of p.gainers) lines.push(row.rank + '. ' + row.symbol + ' ' + signed(row.change_percentage,'%') + ' · ₹' + n(row.current_price));
    lines.push('*Losers*');
    for (const row of p.losers) lines.push(row.rank + '. ' + row.symbol + ' ' + signed(row.change_percentage,'%') + ' · ₹' + n(row.current_price));
    lines.push('50/50 fresh · vs previous official close · ' + ist(input.data_as_of));
    break;
  case 'market.oiis.candidates.changed.v1':
    lines = ['*OIIS CANDIDATES — ' + ist(p.data_as_of) + '*'];
    if (p.long_candidates.length) { lines.push('*LONG*'); for (const row of p.long_candidates) lines.push(row.rank + '. ' + row.symbol + ' · X ' + n(row.xfactor,1) + ' · O ' + n(row.ofactor,1)); }
    if (p.short_candidates.length) { lines.push('*SHORT*'); for (const row of p.short_candidates) lines.push(row.rank + '. ' + row.symbol + ' · X ' + n(row.xfactor,1) + ' · O ' + n(row.ofactor,1)); }
    if (p.added_memberships.length || p.removed_memberships.length) {
      const changes = []; if (p.added_memberships.length) changes.push('Added ' + p.added_memberships.join(', '));
      if (p.removed_memberships.length) changes.push('Removed ' + p.removed_memberships.join(', ')); lines.push(changes.join(' · '));
    }
    lines.push('Only XFactor >70 and OFactor >70','Market intelligence, not an order');
    break;
  case 'market.close.snapshot.v1':
    lines = ['*NIFTY 50 — FINAL CLOSE*','Close *' + n(p.final_close) + '* · ' + signed(p.daily_delta_points,' pts') + ' (' + signed(p.daily_delta_percentage,'%') + ')',
      'Open→close ' + signed(p.open_to_close_percentage,'%') + ' · Range ' + n(p.session_low) + '–' + n(p.session_high) + ' (' + n(p.range_percentage) + '%)',
      'Final · ' + ist(input.data_as_of)];
    break;
}
const message = lines.filter(Boolean).join('\n');
if (!message || message.length > 1800) throw new Error('MARKET_STATUS_MESSAGE_LENGTH_INVALID');
const state = $getWorkflowStaticData('global'); const now = Date.now(); const ttl = 48*60*60*1000;
state.seen = state.seen || {}; for (const [id,at] of Object.entries(state.seen)) if (now-Number(at)>ttl) delete state.seen[id];
if (state.seen[input.event_id]) return [{json:{send:false,suppression_reason:'DUPLICATE_EVENT',event_id:input.event_id}}];
if (input.delivery_test_only === true) return [{json:{send:false,suppression_reason:'TEST_ONLY',event_id:input.event_id,preview:message}}];
return [{json:{send:true,event_id:input.event_id,event_type:input.event_type,correlation_id:input.correlation_id,whatsapp_message:message}}];

const original = $('Validate and Format Whitelisted Event').first().json;
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
state.seen[original.event_id] = Date.now();
return [{json:{accepted:true,event_id:original.event_id,event_type:original.event_type}}];
